INSERT OR IGNORE INTO research_reports(id,report_type,subject_id,title,body_json,research_status,last_reviewed_at) VALUES ('event-nvidia-ceo-transition-2026-11-12','Event','nvidia-ceo-transition-2026-11-12','NVIDIA''s 2026 CEO transition: documented facts and coverage','[{"heading":"Overview","body":"On 12 November 2026 NVIDIA announced that Jensen Huang had resigned as president, chief executive officer, and a board member. The company named Colette Kress interim chief executive and Harvey C. Jones board chair. Those leadership changes are documented in NVIDIA''s own announcement. The announcement does not, by itself, establish the truth of every allegation discussed in contemporaneous news coverage."},{"heading":"Chronology","body":"On 8 November NVIDIA''s board announced an independent investigation. On 10 November independent directors announced outside counsel. On 12 November the company announced the leadership transition. These dates are announcement dates; the precise times of underlying private decisions are not established in the public documents reviewed here."},{"heading":"Contested allegations","body":"News outlets discussed allegations concerning Huang''s personal conduct, a former executive at Megaspeed, and possible national-security implications. This report attributes those allegations to the linked publications. It does not reach an independent finding on espionage, export-control violations, or the board''s private reasoning."},{"heading":"Responses and later developments","body":"The 8 November board statement said it then had no reason to believe national-security or company secrets had been compromised. Later coverage reported debate over Huang''s possible return and further scrutiny. This report remains a draft while claim-level evidence and subsequent developments are reviewed."},{"heading":"Outstanding questions","body":"What findings, if any, will the independent investigation publish? Which claims in the reporting can be checked against primary records? How did coverage change after the board''s later statements?"}]','Draft','2026-11-21');
