INSERT OR IGNORE INTO research_reports(id,report_type,subject_id,title,body_json,research_status,last_reviewed_at) VALUES ('media-board-decision-2026-11-17','Media coverage','nvidia-quarterly-results-2026-11-17','How outlets covered NVIDIA''s board decision on Huang''s return','[{"heading":"Coverage overview","body":"Several checked outlets reported on NVIDIA''s 17 November earnings call and its chair''s statement that the board did not intend to reinstate Huang. AP, TechCrunch, WIRED, and Fortune each used a different headline emphasis. The shared board statement is a documented source; headline similarity is not evidence that outlets coordinated their coverage."},{"heading":"Framing differences","body":"AP framed the board decision alongside pressure from Silicon Valley and other responses. TechCrunch led with the company''s decision and Huang''s earlier public offer. WIRED paired the decision with business performance and support from executives and employees. Fortune''s analysis highlighted questions it said analysts did not ask on the call. These descriptions concern the sampled pieces, not each outlet''s complete coverage."},{"heading":"Reporting versus analysis","body":"The AP, TechCrunch and WIRED entries are classified as news. The Fortune piece is classified as analysis. Those labels describe article form, not credibility. This comparison does not independently verify all claims beyond the cited company statement and checked publisher metadata."},{"heading":"Corrections and limits","body":"No publisher correction has been logged for these sampled articles in the archive. That is not proof none exists. The comparison remains a draft until more publications, byline-level source use, and later updates have been checked."}]','Draft','2026-11-21');
